import{_ as l,C as g,o as d,c,ah as n,E as o,w as r,a as s,j as i}from"./chunks/framework.FcDY0lca.js";const p="/projects/BusLinker/en/latest/assets/image_1.B0Q9spMa.jpg",h="/projects/BusLinker/en/latest/assets/image_1.sZVe2ZoR.png",m="/projects/BusLinker/en/latest/assets/image_2.b2Y48gk-.png",u="/projects/BusLinker/en/latest/assets/image_1.D5HMReeK.png",w="data:image/png;base64,",f="/projects/BusLinker/en/latest/assets/image_4.CgpveApI.png",b="/projects/BusLinker/en/latest/assets/image_5.7seIJAlA.png",v="/projects/BusLinker/en/latest/assets/image_6.tXYpCn5d.png",a="/projects/BusLinker/en/latest/assets/image_7.DcTS_lfD.png",_="/projects/BusLinker/en/latest/assets/image_8.BIf15Lqq.png",y="/projects/BusLinker/en/latest/assets/image_9.C29ZnIPc.png",x="/projects/BusLinker/en/latest/assets/image_10.CV4KQRKt.png",S="/projects/BusLinker/en/latest/assets/image_11.DRlqYgmp.png",k="/projects/BusLinker/en/latest/assets/image_12.DW-I7tq8.png",C="/projects/BusLinker/en/latest/assets/image_13.CHHhwx30.png",T="/projects/BusLinker/en/latest/assets/image_14.CIrgsqST.png",A="/projects/BusLinker/en/latest/assets/image_15.XjMiNrOi.png",B="/projects/BusLinker/en/latest/assets/image_16.jaIRHKtp.png",P="/projects/BusLinker/en/latest/assets/image_17.DZkrHSN5.png",D="/projects/BusLinker/en/latest/assets/image_18.D7_lwbiP.png",q="/projects/BusLinker/en/latest/assets/image_19.wDVt5QOn.png",L="/projects/BusLinker/en/latest/assets/image_20.SujlNI4V.png",I="/projects/BusLinker/en/latest/assets/image_21.cuZI7k4x.png",V="/projects/BusLinker/en/latest/assets/image_22.CFTNB7wm.png",j="/projects/BusLinker/en/latest/assets/image_23.CYwBH1hS.png",z="/projects/BusLinker/en/latest/assets/image_24.CyWqLUDW.png",O="/projects/BusLinker/en/latest/assets/image_25.CuoClLHv.png",M="/projects/BusLinker/en/latest/assets/image_26.DvPw90xD.png",E="/projects/BusLinker/en/latest/assets/image_27.qWJ5pNOY.png",H="/projects/BusLinker/en/latest/assets/image_28.DBjxyB2N.png",U="/projects/BusLinker/en/latest/assets/image_30.DXSNaKCY.png",N="/projects/BusLinker/en/latest/assets/image_29.C1XyzuJV.png",W="/projects/BusLinker/en/latest/assets/image_31.CoA6ko13.png",R="/projects/BusLinker/en/latest/assets/image_2.Cw95frCI.png",$=JSON.parse('{"title":"1. BusLinker V3.0 Servo Debugging Board User Manual","description":"","frontmatter":{},"headers":[],"relativePath":"docs/1_BusLinker_V3.0_Servo_Debugging_Board_User_Manual.md","filePath":"docs/1_BusLinker_V3.0_Servo_Debugging_Board_User_Manual.md"}'),F={name:"docs/1_BusLinker_V3.0_Servo_Debugging_Board_User_Manual.md"};function K(Y,t,X,Z,Q,J){const e=g("center");return d(),c("div",null,[t[3]||(t[3]=n('<h1 id="_1-buslinker-v3-0-servo-debugging-board-user-manual" tabindex="-1">1. BusLinker V3.0 Servo Debugging Board User Manual <a class="header-anchor" href="#_1-buslinker-v3-0-servo-debugging-board-user-manual" aria-label="Permalink to &quot;1. BusLinker V3.0 Servo Debugging Board User Manual&quot;">​</a></h1><h2 id="_1-1-introduction" tabindex="-1">1.1 Introduction <a class="header-anchor" href="#_1-1-introduction" aria-label="Permalink to &quot;1.1 Introduction&quot;">​</a></h2><img loading="lazy" height="1263" width="1000" src="'+p+'" class="common_img" style="width:350px;"><p>The BusLinker V3.0 Servo Debugging Board is a servo debugging tool used for servo testing and parameter configuration with the ServoStudio PC software. The debugging board can also communicate with microcontrollers via serial communication to control servos. Its main features are as follows:</p><ul><li>Supports serial bus servo connections and is compatible with PH2.0, 5264, and 1.25T interfaces. Fully adapts to Hiwonder magnetic encoder intelligent bus servos, enabling plug-and-play connections.</li></ul><ul><li>Built-in eight configurable baud rate levels, with support up to 1,000,000 bps, meeting control requirements in different applications.</li><li>Compatible with multiple controllers. The onboard communication switching interface allows flexible switching between ESP32, STM32, Arduino, Raspberry Pi, and Jetson controllers.</li><li>Supports multiple communication modes, including UART, USB, and single-wire TTL. Servo motion can be quickly controlled using communication commands.</li><li>Dual power input design, providing high-current DC input and terminal block power input. Supports a wide input voltage range from 5 V to 14 V for stable and reliable operation.</li><li>Supports secondary development. Reserved expansion serial ports and provided communication examples facilitate function expansion and further development.</li><li>Compact size with a mini structural design, reducing space usage and improving overall robot integration flexibility.</li><li>Compatible with the LeRobot project.</li></ul><h2 id="_1-2-interfaces-and-power-supply" tabindex="-1">1.2 Interfaces and Power Supply <a class="header-anchor" href="#_1-2-interfaces-and-power-supply" aria-label="Permalink to &quot;1.2 Interfaces and Power Supply&quot;">​</a></h2><h3 id="_1-2-1-interface-description" tabindex="-1">1.2.1 Interface Description <a class="header-anchor" href="#_1-2-1-interface-description" aria-label="Permalink to &quot;1.2.1 Interface Description&quot;">​</a></h3><p>The interfaces of the BusLinker V3.0 Servo Debugging Board are shown in the table below.</p><img loading="lazy" height="477" width="624" src="'+h+'" class="common_img" style="width:350px;"><table border="1"><thead><tr><th style="text-align:center;">Index</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td>① 5264 Bus Servo Port</td><td>Connects bus servos for debugging</td></tr><tr><td>② PH2.0 Bus Servo Port</td><td>Connects bus servos for debugging</td></tr><tr><td>③ 1.25T Bus Servo Port</td><td>Connects bus servos for debugging</td></tr><tr><td>④ Communication Selection Pins</td><td>Switches communication mode between USB and TTL</td></tr><tr><td>⑤ Serial Port Pins</td><td>Used for serial communication with external microcontrollers</td></tr><tr><td>⑥ DC Power Input</td><td>Connects a 5.5 × 2.1 mm DC power adapter</td></tr><tr><td>⑦ Terminal Power Port</td><td>Connects a lithium battery for power supply</td></tr><tr><td>⑧ Type-C Port</td><td>Communicates with PC software or the controller</td></tr></tbody></table><h3 id="_1-2-2-power-supply-description" tabindex="-1">1.2.2 Power Supply Description <a class="header-anchor" href="#_1-2-2-power-supply-description" aria-label="Permalink to &quot;1.2.2 Power Supply Description&quot;">​</a></h3><p>The BusLinker V3.0 board supports two power supply methods: terminal block power supply and DC connector power supply.</p><img loading="lazy" height="345" width="589" src="'+m+'" class="common_img" style="width:450px;"><p>The supported input voltage range is 5–14 V. A 12 V 5 A power adapter or an 11.1 V lithium battery may be used for the power supply.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>When powering the board through the terminal block, ensure that the battery polarity is connected correctly. Do not reverse the positive and negative terminals.</strong></p></div><h2 id="_1-3-pc-software-overview" tabindex="-1">1.3 PC Software Overview <a class="header-anchor" href="#_1-3-pc-software-overview" aria-label="Permalink to &quot;1.3 PC Software Overview&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>The servos and servo horns used in this document are for demonstration purposes only. Refer to the actual hardware in use.</p></div><h3 id="_1-3-1-setting-up-the-pc-software-control-environment" tabindex="-1">1.3.1 Setting Up the PC Software Control Environment <a class="header-anchor" href="#_1-3-1-setting-up-the-pc-software-control-environment" aria-label="Permalink to &quot;1.3.1 Setting Up the PC Software Control Environment&quot;">​</a></h3><p id="anther3.1.1"></p><h4 id="_1-3-1-1-hardware-wiring-and-connections" tabindex="-1">1.3.1.1 Hardware Wiring and Connections <a class="header-anchor" href="#_1-3-1-1-hardware-wiring-and-connections" aria-label="Permalink to &quot;1.3.1.1 Hardware Wiring and Connections&quot;">​</a></h4><p>The required materials are listed in the table below. Here, the HX-30HM magnetic encoder servo and an 11.1 V battery are used as examples.</p><table border="1"><thead><tr><th style="text-align:center;">Item</th><th style="text-align:center;">Quantity</th></tr></thead><tbody><tr><td style="text-align:center;">BusLinker V3.0 Servo Debugging Board</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">HX-30HM</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">Type-C data cable</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">11.1V battery</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">Battery power cable</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">5264 servo connector cable</td><td style="text-align:center;">1</td></tr></tbody></table><ol><li>Connect the servo to the BusLinker V3.0 board via the servo cable to the 5264 3-pin bus servo port.</li><li>Connect the red wire of the adapter cable to the <strong>+</strong> on the board and the black wire to <strong>−</strong>, then connect the USB cable.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><strong>Ensure the battery polarity is correct when connecting the adapter cable. Do not reverse the positive and negative terminals.</strong></li><li><strong>Place the jumper cap on the Servo and USB pins.</strong></li></ul></div><ol start="3"><li><p>Connect the lithium battery to the battery connector cable. The cable is designed to prevent reverse insertion. Do not force it if it does not fit.</p><p>If a lithium battery is not available, use a stable 12 V power supply.</p></li></ol><img loading="lazy" height="787" width="1266" src="'+u+'" class="common_img" style="width:500px;"><h4 id="_1-3-1-2-software-environment-setup" tabindex="-1">1.3.1.2 Software Environment Setup <a class="header-anchor" href="#_1-3-1-2-software-environment-setup" aria-label="Permalink to &quot;1.3.1.2 Software Environment Setup&quot;">​</a></h4><ul><li><strong>ServoStudio Installation</strong></li></ul><p>ServoStudio PC software path: <a href="https://drive.google.com/drive/folders/1ptj8TAkLZG6f0g-88NdwO-Hsus33CskO" target="_blank" rel="noreferrer">Appendix / ServoStudio_0.1.3.exe</a>.</p><p>Double-click to open and use the software.</p><ul><li><strong>Serial Port Driver Installation</strong></li></ul><p>CH341 serial driver installation package path: <a href="https://drive.google.com/drive/folders/1ptj8TAkLZG6f0g-88NdwO-Hsus33CskO" target="_blank" rel="noreferrer">Appendix / ch341ser.exe</a>.</p><p>Installation steps:</p><p>① Double-click to open the CH341 serial driver installation package.</p><img loading="lazy" height="24" width="262" src="'+w+'" class="common_img" style="width:400px;"><p>② Click <code>Install</code> to install the driver.</p><img loading="lazy" height="379" width="666" src="'+f+'" class="common_img" style="width:500px;"><p>③ When a popup confirms successful installation, click <strong>OK</strong>.</p><img loading="lazy" height="145" width="342" src="'+b+'" class="common_img" style="width:300px;"><h3 id="_1-3-2-pc-software-testing" tabindex="-1">1.3.2 PC Software Testing <a class="header-anchor" href="#_1-3-2-pc-software-testing" aria-label="Permalink to &quot;1.3.2 PC Software Testing&quot;">​</a></h3><h4 id="_1-3-2-1-servo-status-description" tabindex="-1">1.3.2.1 Servo Status Description <a class="header-anchor" href="#_1-3-2-1-servo-status-description" aria-label="Permalink to &quot;1.3.2.1 Servo Status Description&quot;">​</a></h4><p>The following three images show the three basic servo positions — central position, maximum angle, and minimum angle. For visual demonstration, a servo horn is inserted as an example, with the label placed on the right-side servo arm to indicate the initial position.</p><img loading="lazy" height="546" width="552" src="'+v+'" class="common_img" style="width:300px;">',44)),o(e,null,{default:r(()=>[...t[0]||(t[0]=[s("Adjustable central position: servo angle 180°, corresponding position 2047",-1)])]),_:1}),t[4]||(t[4]=i("img",{loading:"lazy",height:"470",width:"368",src:a,class:"common_img",style:{width:"300px"}},null,-1)),o(e,null,{default:r(()=>[...t[1]||(t[1]=[s("Maximum position within one rotation: servo angle 360°, corresponding position 4095",-1)])]),_:1}),t[5]||(t[5]=i("img",{loading:"lazy",height:"470",width:"368",src:a,class:"common_img",style:{width:"300px"}},null,-1)),o(e,null,{default:r(()=>[...t[2]||(t[2]=[s("Minimum position within one rotation: servo angle 0°, corresponding position 0",-1)])]),_:1}),t[6]||(t[6]=n('<h4 id="_1-3-2-2-reading-and-configuring-servo-information" tabindex="-1">1.3.2.2 Reading and Configuring Servo Information <a class="header-anchor" href="#_1-3-2-2-reading-and-configuring-servo-information" aria-label="Permalink to &quot;1.3.2.2 Reading and Configuring Servo Information&quot;">​</a></h4><ol><li>Open the BusLinker V3.0 board software located at <a href="https://drive.google.com/drive/folders/19xPsh_8OnDMBHe_g1RRZSTcbwcvie8lP" target="_blank" rel="noreferrer">2. Softwares / Servo Debugging Board Software</a>. On the left side of the interface, select the serial port, then click the button to open the port. The default baud rate is 1,000,000, then click <strong>Connect</strong>.</li></ol><img loading="lazy" height="275" width="170" src="'+_+'" class="common_img" style="width:200px;"><ol start="2"><li>After the serial port is connected, click <strong>Scan</strong> in the <strong>Dashboard</strong>. The software will scan servos with IDs from 1 to 253. The detected servos will be displayed in the interface.</li></ol><img loading="lazy" height="1009" width="1920" src="'+y+'" class="common_img" style="width:1200px;"><img loading="lazy" height="1009" width="1920" src="'+x+'" class="common_img" style="width:1200px;"><ol start="3"><li>Click <strong>Config</strong> to enter the parameter configuration interface. Here, the servo parameters can be viewed and configured as needed.</li></ol><img loading="lazy" height="1009" width="1920" src="'+S+'" class="common_img" style="width:1200px;"><p>(1) Basic Configuration</p><p>① <strong>General — Basic Configuration</strong></p><img loading="lazy" height="221" width="563" src="'+k+'" class="common_img" style="width:600px;"><p>In this panel, the servo ID and the baud rate for communication between the PC software and the servo can be changed. Servo IDs range from 1 to 253, and eight baud rate options are available.</p><p>② <strong>Control Mode — Operation Mode</strong></p><img loading="lazy" height="229" width="555" src="'+C+'" class="common_img" style="width:600px;"><p>In this panel, the servo can be set to three modes: <strong>Position</strong>, <strong>Velocity (Closed-Loop)</strong>, and <strong>PWM (Open-Loop)</strong>.</p><p>In <strong>Position</strong> mode, the servo operates in servo mode. In <strong>Velocity (Closed-Loop)</strong> and <strong>PWM (Open-Loop)</strong> modes, the servo operates in motor mode.</p><p>③ <strong>Torque — Torque Control</strong></p><img loading="lazy" height="214" width="549" src="'+T+'" class="common_img" style="width:600px;"><p>This panel is used to set the <strong>Startup Torque</strong> and the <strong>Torque Limit</strong>. The Startup Torque is the minimum output torque for startup, and the Torque Limit is the maximum output torque limit. Set 1000 = 100% × Stall Torque.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>If the torque is set too low, the servo may fail to rotate.</strong></p></div><p>(2) Motion Control</p><p>① <strong>Position Control — Position Parameters</strong></p><img loading="lazy" height="272" width="563" src="'+A+'" class="common_img" style="width:600px;"><ul><li><strong>Offset — Position correction used to calibrate servo deviation.</strong> The range is -2047 to 2047. If the servo horn cannot be installed in a cross posture due to deviation, adjust this parameter to correct the offset.</li><li><strong>Min/Max Angle — Minimum and maximum angle limits</strong> for restricting the servo rotation range. The range is -30719 to 30719. In absolute position mode, the maximum servo position range is -30719 to 30719. Position 0 to 4095 corresponds to 0° to 360°, so the maximum rotation range is approximately ±7.5 turns. The rotation range can be set within this range according to requirements.</li></ul><p>② <strong>Position PID — Position Closed-Loop Parameters</strong></p><img loading="lazy" height="276" width="559" src="'+B+'" class="common_img" style="width:600px;"><p>Three parameters are used to adjust the servo position error: <strong>P</strong> determines the influence of the current position error on the control signal. <strong>I</strong> reduces long-term static error and normally does not need adjustment. <strong>D</strong> reduces the rate of change of error, improving system stability. These parameters can be adjusted according to requirements to achieve the desired performance.</p><p>③ <strong>Velocity PID — Velocity Closed-Loop Parameters</strong></p><img loading="lazy" height="266" width="562" src="'+P+'" class="common_img" style="width:600px;"><p>Two parameters are used to adjust the servo speed error, ensuring motion at the desired speed and maintaining precise speed control. These parameters can be adjusted according to requirements to achieve the desired performance.</p><p>(3) <strong>Protection</strong></p><img loading="lazy" height="544" width="1693" src="'+D+'" class="common_img" style="width:1200px;"><p>Thresholds for each panel can be adjusted and the actions that trigger protection or alarms can be selected according to requirements.</p><ul><li><p><strong>Voltage</strong> — Under Voltage and Over Voltage threshold, range 0–254, unit 0.1 V.</p></li><li><p><strong>Current</strong> — Current Max threshold, range 0–6000, unit mA. Hold is the overcurrent protection time threshold, with a range of 0–254, and a unit of 10 ms.</p></li><li><p><strong>Overload</strong> — Load Max, range 0–100, unit 1%, maximum corresponds to the maximum torque. Hold is the overload time threshold, with a range of 0–254, and a unit of 10 ms. Torque Max is the maximum output torque after triggering overload protection, with a range of 0–100, and a unit of 1%.</p></li><li><p><strong>Temperature</strong> — Over-temperature protection threshold, range 0–100, unit °C.</p></li></ul><h4 id="_1-3-2-3-servo-operation-control" tabindex="-1">1.3.2.3 Servo Operation Control <a class="header-anchor" href="#_1-3-2-3-servo-operation-control" aria-label="Permalink to &quot;1.3.2.3 Servo Operation Control&quot;">​</a></h4><p>Click the <strong>Monitor</strong> option on the left to enter the servo debugging interface.</p><img loading="lazy" height="1009" width="1920" src="'+q+'" class="common_img" style="width:1200px;"><p>The interface consists of five areas:<br> ① Servo operation parameter waveform area. ② Command area for servo operation. ③ Auto Sweep area. ④ Step Mode area. ⑤ Feedback area.</p><p>The five areas are described as follows:</p><p>① Servo Operation Parameter Waveform Area</p><img loading="lazy" height="625" width="1710" src="'+L+'" class="common_img" style="width:1200px;"><p>This area provides a visual display of the changes in six servo parameters during operation. On the right, switches can be enabled to display the desired parameters. Below the parameter switches, a dropdown menu allows selection of the time per division for the waveform display.</p><p>② Command Area for Servo Operation</p><img loading="lazy" height="281" width="725" src="'+I+'" class="common_img" style="width:700px;"><p>This area allows configuration of the three servo write modes: <strong>Write</strong>, <strong>SyncWrite</strong>, and <strong>RegWrite</strong>. Detailed information about these write modes can be found in the <a href="https://drive.google.com/file/d/1VbDaEjqYL1_nTGah5S9nptFQBXAYzW2D/view?usp=sharing" target="_blank" rel="noreferrer">Hiwonder Magnetic Encoder Bus Servo Communication Protocol Document</a>. The Torque switch controls whether the servo is powered. When the switch is turned off, the servo stops outputting torque. If a servo horn is installed, it can then be manually rotated. The slider in the middle can be used to directly control the servo position, with a range of 0–4095. Below the slider, the following parameters can be set for servo movement:<br><strong>Accel</strong> — acceleration, range 0–254, unit 100 steps/s².<br><strong>Speed</strong> — speed, range 0–3400, unit steps/s.<br><strong>Target</strong> — target position, range -30719 to 30719, unit steps.<br><strong>Time</strong> — time, range 0–1000. At the bottom, three buttons are provided:<br><strong>As Center</strong> sets the current target position as the central position. <strong>Action</strong> triggers motion in asynchronous write mode. <strong>Apply</strong> sends parameters to the servo in normal write and synchronous write modes**</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><strong>In Position mode, the Time parameter is ignored.</strong></li><li><strong>In Velocity (Closed-Loop) mode, only the Speed parameter is effective.</strong></li><li><strong>In PWM (Open-Loop) mode, only the Time parameter is effective.</strong></li></ul></div><p>③ Auto Sweep Area</p><img loading="lazy" height="139" width="699" src="'+V+'" class="common_img" style="width:700px;"><p>This area allows setting the <strong>Start</strong> and <strong>End</strong> positions of the servo, with a range of -30719 to 30719 in steps. <strong>Delay</strong> specifies the interval time between sending the <strong>Start</strong> and <strong>End</strong> positions. <strong>Speed</strong> is set in the Command area for servo operation. Clicking <strong>Start</strong> causes the servo to move back and forth between the two positions.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>If the delay is shorter than the time required to move between the two positions, the current motion will be interrupted.</strong></p></div><p>④ Step Mode Area</p><img loading="lazy" height="134" width="693" src="'+j+'" class="common_img" style="width:700px;"><p>In this area, the <strong>Start</strong> and <strong>End</strong> positions of the servo can be set, with a range of -4095 to 4095 in steps. <strong>Step</strong> specifies the step size, with a range of 0–1000 in steps. <strong>Delay</strong> specifies the interval time between steps. Clicking <strong>Start</strong> causes the servo to move from the <strong>Start</strong> to the <strong>End</strong> position according to the specified <strong>Step</strong> and <strong>Delay</strong> values.</p><p>⑤ Feedback Area</p><img loading="lazy" height="277" width="298" src="'+z+'" class="common_img" style="width:300px;"><p>This area provides a visual display of the servo status and all relevant parameters during operation.</p><h4 id="_1-3-2-4-magnetic-encoder-servo-firmware-flashing" tabindex="-1">1.3.2.4 Magnetic Encoder Servo Firmware Flashing <a class="header-anchor" href="#_1-3-2-4-magnetic-encoder-servo-firmware-flashing" aria-label="Permalink to &quot;1.3.2.4 Magnetic Encoder Servo Firmware Flashing&quot;">​</a></h4><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>HX-30HM is used as the example in this section.</strong></p></div><p>Complete the hardware connections as described in the <a href="#anther3.1.1">1.3.1.1 Hardware Wiring and Connections</a> section.</p><p>Click <strong>Firmware</strong>, then click <strong>Click or drag firmware file here</strong>.</p><img loading="lazy" height="1009" width="1920" src="'+O+'" class="common_img" style="width:1200px;"><p>Select the firmware file <strong>HX-30HM_V3.9_20251023.sfw</strong>, then click <strong>Open</strong>.</p><img loading="lazy" height="533" width="946" src="'+M+'" class="common_img" style="width:800px;"><p>Click <strong>Force Update</strong>, then click <strong>Update</strong>.</p><img loading="lazy" height="1009" width="1920" src="'+E+'" class="common_img" style="width:1200px;"><p>When the interface shown below appears, the firmware update process has started. At this time, unplug and reconnect the servo cable.</p><img loading="lazy" height="1009" width="1920" src="'+H+'" class="common_img" style="width:1200px;"><p>When the content highlighted in red appears, the servo firmware update is complete.</p><img loading="lazy" height="1009" width="1920" src="'+U+'" class="common_img" style="width:1200px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>If a handshake failure message appears, as shown below, follow the steps above to retry the process, click Update, and perform the firmware update again.</strong></p></div><img loading="lazy" height="1009" width="1920" src="'+N+'" class="common_img" style="width:1200px;"><h4 id="_1-3-2-5-software-system-settings" tabindex="-1">1.3.2.5 Software System Settings <a class="header-anchor" href="#_1-3-2-5-software-system-settings" aria-label="Permalink to &quot;1.3.2.5 Software System Settings&quot;">​</a></h4><p>Click <strong>Settings</strong> in the left panel to enter the software system settings interface.</p><img loading="lazy" height="1009" width="1920" src="'+W+'" class="common_img" style="width:1200px;"><p>Four features are available, including System Info, Interface, Visualization, and Update Rate.</p><p>① System Info:</p><p>The system information section displays the software version, creation time, operating system, and runtime duration.</p><p>② Interface:</p><p>The interface settings section allows switching the software language between English and Chinese.</p><p>③ Visualization:</p><p>Line Width: Adjusts the line thickness of the servo parameter waveform displayed in the servo debugging interface.</p><p>Smoothing: Reduces short-term fluctuations, noise, or randomness in the data.</p><p>Level: Adjusts the smoothing factor using the slider. A smaller value results in slower and more stable data changes with stronger noise resistance. A larger value results in faster and more responsive data changes with weaker noise resistance.</p><p>Filter Outliers: Detects abnormal values in the waveform.</p><p>④ Update Rate:</p><p>Adjusts the update frequency of Dashboard Refresh, Monitor Sample Rate, and Config Refresh.</p><h2 id="_1-4-specifications" tabindex="-1">1.4 Specifications <a class="header-anchor" href="#_1-4-specifications" aria-label="Permalink to &quot;1.4 Specifications&quot;">​</a></h2><ul><li><strong>Dimensions:</strong></li></ul><img loading="lazy" height="360" width="558" src="'+R+'" class="common_img" style="width:600px;"><ul><li><strong>Other Specifications:</strong></li></ul><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Product</strong></th><th style="text-align:center;"><strong>BusLinker V3.0 Servo Debugging Board</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><strong>Brand</strong></td><td style="text-align:center;"><strong>Hiwonder</strong></td></tr><tr><td style="text-align:center;"><strong>Weight</strong></td><td style="text-align:center;"><strong>10g</strong></td></tr><tr><td style="text-align:center;"><strong>Size</strong></td><td style="text-align:center;"><strong>42 x 33 x 15 mm</strong></td></tr><tr><td style="text-align:center;"><strong>Communication methods</strong></td><td style="text-align:center;"><strong>Serial communication</strong></td></tr><tr><td style="text-align:center;"><strong>Input voltage</strong></td><td style="text-align:center;"><strong>5-14V</strong></td></tr><tr><td style="text-align:center;"><strong>Power input</strong></td><td style="text-align:center;"><strong>1 × DC power connector, 1 × terminal block</strong></td></tr><tr><td style="text-align:center;"><strong>Communication interface</strong></td><td style="text-align:center;"><strong>1 × USB serial, 1 × TTL serial</strong></td></tr><tr><td style="text-align:center;"><strong>Response element</strong></td><td style="text-align:center;"><strong>3 × LED</strong></td></tr><tr><td style="text-align:center;"><strong>Control method</strong></td><td style="text-align:center;"><strong>PC software</strong></td></tr><tr><td style="text-align:center;"><strong>Mounting hole distance</strong></td><td style="text-align:center;"><strong>36 x 28 mm</strong></td></tr><tr><td style="text-align:center;"><strong>External microcontroller</strong></td><td style="text-align:center;"><strong>Supports</strong></td></tr></tbody></table>',91))])}const tt=l(F,[["render",K]]);export{$ as __pageData,tt as default};
